def __hash__(self) -> int:
    return hash(self.as_rgb_tuple())

def __eq__(self, other: Any) -> bool:
    if not isinstance(other, Color):
        return NotImplemented
    # Compare RGB values and alpha values
    return self._rgba.r == other._rgba.r and \
           self._rgba.g == other._rgba.g and \
           self._rgba.b == other._rgba.b and \
           self._rgba.alpha == other._rgba.alpha
